driverScript:
module.exports = {
    msgId: 1,
    onConnect: function(transport, config) {
        engine.setStatus("connecting", "Connecting to Home Assistant WebSocket...");
    },
    onTransportReady: function(transport, config) {
        engine.setStatus("authenticating", "Authenticating with Access Token...");
    },
    onAction: function(transport, actionId, params) {
        var domain = params.domain || "light";
        var service = params.service || "toggle";
        var entityId = params.entity_id || "";

        var payload = {
            id: ++this.msgId,
            type: "call_service",
            domain: domain,
            service: service,
            service_data: {}
        };
        if (entityId) {
            payload.service_data.entity_id = entityId;
        }
        transport.sendJSON(payload);
        return "Called " + domain + "." + service + (entityId ? " on " + entityId : "");
    },
    onMessage: function(transport, text, bytes) {
        var msg;
        try { msg = JSON.parse(text); } catch(e) { return; }

        if (msg.type === "auth_required") {
            var token = engine.secret("access_token") || engine.secret("token") || "";
            transport.sendJSON({
                type: "auth",
                access_token: token
            });
            return;
        }

        if (msg.type === "auth_ok") {
            engine.setStatus("connected", "Home Assistant Connected");
            transport.sendJSON({
                id: ++this.msgId,
                type: "subscribe_events",
                event_type: "state_changed"
            });
            return;
        }

        if (msg.type === "auth_invalid") {
            engine.setStatus("failed", "Authentication Failed: " + (msg.message || "Invalid Token"));
            return;
        }

        if (msg.type === "event" && msg.event && msg.event.event_type === "state_changed") {
            var data = msg.event.data;
            if (data && data.entity_id && data.new_state) {
                var cleanEntity = data.entity_id.replace(/\./g, "_");
                engine.setVariable("ha_" + cleanEntity + "_state", String(data.new_state.state));
            }
        }
    }
};
